<?php
 namespace QQWorld\Translation\Test\Unit\Model\Inline; class CacheManagerTest extends \PHPUnit\Framework\TestCase { protected $model; protected $eventManagerMock; protected $translateResourceMock; protected $localeResolverMock; protected $fileManagerMock; protected function setUp() { $this->eventManagerMock = $this->getMockBuilder(\QQWorld\Framework\Event\ManagerInterface::class) ->disableOriginalConstructor() ->setMethods([]) ->getMock(); $this->translateResourceMock = $this->getMockBuilder(\QQWorld\Framework\Translate\ResourceInterface::class) ->disableOriginalConstructor() ->setMethods([]) ->getMock(); $this->localeResolverMock = $this->getMockBuilder(\QQWorld\Framework\Locale\ResolverInterface::class) ->disableOriginalConstructor() ->setMethods([]) ->getMock(); $this->fileManagerMock = $this->getMockBuilder(\QQWorld\Translation\Model\FileManager::class) ->disableOriginalConstructor() ->setMethods([]) ->getMock(); $objectManagerHelper = new \QQWorld\Framework\TestFramework\Unit\Helper\ObjectManager($this); $this->model = $objectManagerHelper->getObject( \QQWorld\Translation\Model\Inline\CacheManager::class, [ 'eventManager' => $this->eventManagerMock, 'translateResource' => $this->translateResourceMock, 'localeResolver' => $this->localeResolverMock, 'fileManager' => $this->fileManagerMock ] ); } public function testUpdateAndGetTranslations() { $translations = ['phrase1' => 'translated1', 'phrase2' => 'translated2']; $this->eventManagerMock->expects($this->once())->method('dispatch'); $this->translateResourceMock->expects($this->once())->method('getTranslationArray')->willReturn($translations); $this->localeResolverMock->expects($this->once())->method('getLocale')->willReturn('en_US'); $this->fileManagerMock->expects($this->once())->method('updateTranslationFileContent'); $this->assertEquals($translations, $this->model->updateAndGetTranslations()); } } 